<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>番茄钟</title>
  <style>
    :root {
      --bg-1: #0f172a;
      --bg-2: #1e1b2e;
      --card-bg: rgba(255, 255, 255, 0.06);
      --card-border: rgba(255, 255, 255, 0.1);
      --text-primary: #f8fafc;
      --text-secondary: #94a3b8;
      --accent: #ff6b6b;
      --accent-glow: rgba(255, 107, 107, 0.35);
      --accent-soft: rgba(255, 107, 107, 0.14);
      --ring-track: rgba(255, 255, 255, 0.08);
      --transition: 0.4s cubic-bezier(0.22, 1, 0.36, 1);
    }
    body.break-mode {
      --bg-2: #0f292e;
      --accent: #34d399;
      --accent-glow: rgba(52, 211, 153, 0.35);
      --accent-soft: rgba(52, 211, 153, 0.14);
    }
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }
    body {
      min-height: 100vh;
      display: grid;
      place-items: center;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
      color: var(--text-primary);
      background: radial-gradient(circle at 20% 20%, var(--bg-2), var(--bg-1) 70%);
      transition: background var(--transition);
      padding: 20px;
      user-select: none;
    }
    .app {
      width: 100%;
      max-width: 400px;
      background: var(--card-bg);
      border: 1px solid var(--card-border);
      border-radius: 32px;
      padding: 32px 28px 28px;
      backdrop-filter: blur(24px);
      -webkit-backdrop-filter: blur(24px);
      box-shadow: 0 24px 64px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.08);
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 28px;
    }
    .mode-switch {
      display: grid;
      grid-template-columns: 1fr 1fr;
      width: 100%;
      background: rgba(0, 0, 0, 0.25);
      padding: 5px;
      border-radius: 16px;
      position: relative;
      border: 1px solid rgba(255, 255, 255, 0.06);
    }
    .mode-btn {
      background: transparent;
      border: none;
      color: var(--text-secondary);
      font-size: 14px;
      font-weight: 600;
      padding: 10px 0;
      border-radius: 12px;
      cursor: pointer;
      transition: color 0.25s ease, background 0.25s ease;
      letter-spacing: 0.5px;
    }
    .mode-btn.active {
      background: var(--accent-soft);
      color: var(--accent);
      box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.06);
    }
    .mode-btn:hover:not(.active) {
      color: var(--text-primary);
    }
    .timer-wrapper {
      position: relative;
      width: 260px;
      height: 260px;
      display: grid;
      place-items: center;
    }
    .timer-svg {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      transform: rotate(-90deg);
      overflow: visible;
    }
    .ring-bg {
      fill: none;
      stroke: var(--ring-track);
      stroke-width: 10;
    }
    .ring-progress {
      fill: none;
      stroke: var(--accent);
      stroke-width: 10;
      stroke-linecap: round;
      filter: drop-shadow(0 0 12px var(--accent-glow));
      transition: stroke var(--transition), stroke-dashoffset 0.3s linear;
    }
    .timer-center {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 6px;
      z-index: 1;
    }
    .time-display {
      font-size: 56px;
      font-weight: 700;
      letter-spacing: 2px;
      font-variant-numeric: tabular-nums;
      line-height: 1;
    }
    .status-text {
      font-size: 13px;
      color: var(--text-secondary);
      letter-spacing: 1.5px;
      text-transform: uppercase;
    }
    .controls {
      display: flex;
      align-items: center;
      gap: 14px;
      width: 100%;
    }
    .btn {
      border: none;
      cursor: pointer;
      font-family: inherit;
      font-weight: 600;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      transition: transform 0.15s ease, box-shadow 0.25s ease, background 0.25s ease, color 0.25s ease;
    }
    .btn:active {
      transform: scale(0.97);
    }
    .btn-primary {
      flex: 1;
      height: 52px;
      border-radius: 16px;
      background: var(--accent);
      color: #0b1120;
      font-size: 16px;
      box-shadow: 0 10px 28px var(--accent-glow);
    }
    .btn-primary:hover {
      filter: brightness(1.08);
    }
    .btn-secondary {
      width: 52px;
      height: 52px;
      border-radius: 16px;
      background: rgba(255, 255, 255, 0.07);
      color: var(--text-primary);
      border: 1px solid rgba(255, 255, 255, 0.08);
    }
    .btn-secondary:hover {
      background: rgba(255, 255, 255, 0.13);
    }
    .footer {
      width: 100%;
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-top: 16px;
      border-top: 1px solid rgba(255, 255, 255, 0.08);
      font-size: 13px;
      color: var(--text-secondary);
    }
    .dots {
      display: flex;
      gap: 6px;
      align-items: center;
    }
    .dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: rgba(255, 255, 255, 0.15);
      transition: background 0.3s ease, box-shadow 0.3s ease;
    }
    .dot.filled {
      background: var(--accent);
      box-shadow: 0 0 8px var(--accent-glow);
    }
    .icon {
      width: 20px;
      height: 20px;
      fill: currentColor;
    }
  </style>
</head>
<body>
  <main class="app">
    <div class="mode-switch" role="tablist">
      <button class="mode-btn active" id="workTab" role="tab" aria-selected="true">专注 25:00</button>
      <button class="mode-btn" id="breakTab" role="tab" aria-selected="false">休息 05:00</button>
    </div>
    <div class="timer-wrapper">
      <svg class="timer-svg" viewBox="0 0 260 260">
        <circle class="ring-bg" cx="130" cy="130" r="118"></circle>
        <circle class="ring-progress" id="progressRing" cx="130" cy="130" r="118"></circle>
      </svg>
      <div class="timer-center">
        <div class="time-display" id="timeDisplay">25:00</div>
        <div class="status-text" id="statusText">准备开始</div>
      </div>
    </div>
    <div class="controls">
      <button class="btn btn-primary" id="toggleBtn">
        <svg class="icon" id="toggleIcon" viewBox="0 0 24 24">
          <path d="M8 5v14l11-7z" />
        </svg>
        <span id="toggleLabel">开始</span>
      </button>
      <button class="btn btn-secondary" id="resetBtn" title="重置" aria-label="重置">
        <svg class="icon" viewBox="0 0 24 24">
          <path d="M17.65 6.35A7.958 7.958 0 0 0 12 4c-4.42 0-7.99 3.58-7.99 8s3.57 8 7.99 8c3.73 0 6.84-2.55 7.73-6h-2.08A5.99 5.99 0 0 1 12 18c-3.31 0-6-2.69-6-6s2.69-6 6-6c1.66 0 3.14.69 4.22 1.78L13 11h7V4l-2.35 2.35z" />
        </svg>
      </button>
    </div>
    <div class="footer">
      <span>已完成番茄：<strong id="countDisplay" style="color: var(--text-primary)">0</strong></span>
      <div class="dots" id="dots">
        <span class="dot"></span>
        <span class="dot"></span>
        <span class="dot"></span>
        <span class="dot"></span>
      </div>
    </div>
  </main>
  <script>
    const DURATIONS = {
      work: 25 * 60,
      break: 5 * 60
    };
    const RADIUS = 118;
    const CIRCUMFERENCE = 2 * Math.PI * RADIUS;
    const progressRing = document.getElementById('progressRing');
    const timeDisplay = document.getElementById('timeDisplay');
    const statusText = document.getElementById('statusText');
    const toggleBtn = document.getElementById('toggleBtn');
    const toggleIcon = document.getElementById('toggleIcon');
    const toggleLabel = document.getElementById('toggleLabel');
    const resetBtn = document.getElementById('resetBtn');
    const workTab = document.getElementById('workTab');
    const breakTab = document.getElementById('breakTab');
    const countDisplay = document.getElementById('countDisplay');
    const dots = document.querySelectorAll('.dot');
    progressRing.style.strokeDasharray = `${CIRCUMFERENCE}`;
    progressRing.style.strokeDashoffset = '0';
    let mode = 'work';
    let remaining = DURATIONS.work;
    let isRunning = false;
    let timerId = null;
    let endTime = null;
    let completedCount = 0;
    let audioCtx = null;
    function initAudio() {
      if (!audioCtx) {
        const AudioContextClass = window.AudioContext || window.webkitAudioContext;
        audioCtx = new AudioContextClass();
      }
      if (audioCtx.state === 'suspended') {
        audioCtx.resume();
      }
    }
    function playChime() {
      initAudio();
      const now = audioCtx.currentTime;
      const notes = [880, 1108.73, 1318.51];
      notes.forEach((freq, i) => {
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        const start = now + i * 0.12;
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, start);
        gain.gain.setValueAtTime(0.001, start);
        gain.gain.exponentialRampToValueAtTime(0.22, start + 0.02);
        gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.75);
        osc.connect(gain);
        gain.connect(audioCtx.destination);
        osc.start(start);
        osc.stop(start + 0.8);
      });
    }
    function formatTime(sec) {
      const m = Math.floor(sec / 60).toString().padStart(2, '0');
      const s = (sec % 60).toString().padStart(2, '0');
      return `${m}:${s}`;
    }
    function updateUI() {
      const total = DURATIONS[mode];
      const progress = 1 - remaining / total;
      const offset = CIRCUMFERENCE * progress;
      timeDisplay.textContent = formatTime(remaining);
      progressRing.style.strokeDashoffset = `${offset}`;
      document.title = `${formatTime(remaining)} · ${mode === 'work' ? '专注' : '休息'}`;
      if (isRunning) {
        toggleLabel.textContent = '暂停';
        toggleIcon.innerHTML = '<path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/>';
        statusText.textContent = mode === 'work' ? '专注进行中' : '放松休息中';
      } else {
        toggleLabel.textContent = remaining < total && remaining > 0 ? '继续' : '开始';
        toggleIcon.innerHTML = '<path d="M8 5v14l11-7z"/>';
        statusText.textContent = remaining < total && remaining > 0 ? '已暂停' : (mode === 'work' ? '准备专注' : '准备休息');
      }
      countDisplay.textContent = completedCount;
      const cyclePos = completedCount % 4;
      dots.forEach((dot, idx) => {
        dot.classList.toggle('filled', idx < (cyclePos === 0 && completedCount > 0 ? 4 : cyclePos));
      });
    }
    function setMode(newMode) {
      stopTimer();
      mode = newMode;
      remaining = DURATIONS[mode];
      document.body.classList.toggle('break-mode', mode === 'break');
      workTab.classList.toggle('active', mode === 'work');
      breakTab.classList.toggle('active', mode === 'break');
      workTab.setAttribute('aria-selected', String(mode === 'work'));
      breakTab.setAttribute('aria-selected', String(mode === 'break'));
      updateUI();
    }
    function startTimer() {
      initAudio();
      if (isRunning) return;
      isRunning = true;
      endTime = Date.now() + remaining * 1000;
      updateUI();
      timerId = setInterval(() => {
        const left = Math.max(0, Math.ceil((endTime - Date.now()) / 1000));
        if (left !== remaining) {
          remaining = left;
          updateUI();
        }
        if (remaining <= 0) {
          handleComplete();
        }
      }, 200);
    }
    function stopTimer() {
      isRunning = false;
      if (timerId) {
        clearInterval(timerId);
        timerId = null;
      }
      endTime = null;
    }
    function handleComplete() {
      stopTimer();
      playChime();
      if (mode === 'work') {
        completedCount += 1;
        setMode('break');
        statusText.textContent = '专注完成，休息一下';
      } else {
        setMode('work');
        statusText.textContent = '休息结束，开始专注';
      }
    }
    toggleBtn.addEventListener('click', () => {
      if (isRunning) {
        stopTimer();
        updateUI();
      } else {
        startTimer();
      }
    });
    resetBtn.addEventListener('click', () => {
      stopTimer();
      remaining = DURATIONS[mode];
      updateUI();
    });
    workTab.addEventListener('click', () => setMode('work'));
    breakTab.addEventListener('click', () => setMode('break'));
    updateUI();
  </script>
</body>
</html>
